@Entity
public class Member {
    @Id @GeneratedValue
    @Column(name = "MEMBER_ID")
    private Long id;

    private String username;

    @ManyToOne                         // 회원(N) : 팀(1)
    @JoinColumn(name = "TEAM_ID")      // 이 FK 컬럼으로 조인한다
    private Team team;                 // ← 참조

    protected Member() {}
}

@Entity
